import { useEffect, useState, type Dispatch, type FormEvent, type ReactElement, type ReactNode, type SetStateAction } from 'react';
import { Activity, AlertTriangle, ArrowRight, Bell, BellRing, BrainCircuit, Building2, Check, ChevronRight, CloudRain, CloudSun, Database, FileWarning, Gauge, Globe2, History, Languages, Layers3, LifeBuoy, LocateFixed, LogIn, Map, Menu, MessageSquare, Mountain, Network, Radio, RefreshCw, Route as RouteIcon, Save, Send, Settings2, Shield, Siren, SlidersHorizontal, Sparkles, Sun, Target, TrafficCone, TrendingUp, UsersRound, X, Zap, type LucideIcon } from 'lucide-react';
import { Link, Route, Router as WouterRouter, Switch, useLocation } from 'wouter';

type RiskLevel = 'Critical' | 'High' | 'Moderate' | 'Low';
type Role = 'State Command' | 'District Officer' | 'Field Responder';
type RiskZone = { id: string; name: string; state: string; district: string; score: number; level: RiskLevel; rainfall24h: number; rainfall7d: number; soilMoisture: number; slope: number; elevation: number; roadDistance: number; population: number; villages: number; action: string; coordinates: [number, number] };
type FieldReport = { id: string; location: string; type: string; severity: RiskLevel; description: string; time: string; status: 'New' | 'Triaged' | 'Dispatched'; photoName: string };
type Alert = { id: string; severity: RiskLevel; zone: string; message: string; time: string; acknowledged: boolean; channels: string[] };
type Sensor = { id: string; name: string; status: 'Online' | 'Warning' | 'Offline'; lastSeen: string; value: string };

